function.ModelicaImplementation:
function(p :: Real * h :: Real) => RealEdwardsTest_IAPWS_CritFlow.pipe.Medium.T_phfunction EdwardsTest_IAPWS_CritFlow.pipe.Medium.T_ph "Temperature [K] from (p, h)"
  input Real p "Pressure [Pa]";
  input Real h "Specific enthalpy [J/kg]";
  output Real T_val;
  protected Integer reg = EdwardsTest_IAPWS_CritFlow.pipe.Medium.region_ph(p, h);
  protected Real hf = library.Media.IF97.Saturation.h_f(p);
  protected Real hg = library.Media.IF97.Saturation.h_g(p);
  protected Real T_s = library.Media.IF97.Saturation.T_sat(p);
algorithm
  if reg == 1 then
    T_val := library.Media.IF97.Region1.T_ph(p, h);
  elseif reg == 2 then
    T_val := library.Media.IF97.Region2.T_ph(p, h);
  else
    T_val := T_s;
  end if;
end EdwardsTest_IAPWS_CritFlow.pipe.Medium.T_ph;

function(p :: Real * h :: Real) => RealEdwardsTest_IAPWS_CritFlow.pipe.Medium.drho_dh_pfunction EdwardsTest_IAPWS_CritFlow.pipe.Medium.drho_dh_p "∂ρ/∂h|p [kg/(m³·J/kg)] from (p, h)"
  input Real p "Pressure [Pa]";
  input Real h "Specific enthalpy [J/kg]";
  output Real val;
  protected Integer reg = EdwardsTest_IAPWS_CritFlow.pipe.Medium.region_ph(p, h);
  protected Real T_val;
algorithm
  if reg == 1 then
    T_val := library.Media.IF97.Region1.T_ph(p, h);
    val := library.Media.IF97.Derivatives.drho_dh_p_R1(p, T_val);
  elseif reg == 2 then
    T_val := library.Media.IF97.Region2.T_ph(p, h);
    val := library.Media.IF97.Derivatives.drho_dh_p_R2(p, T_val);
  else
    val := -library.Media.IF97.Saturation.rho_ph_2phase(p, h) ^ 2.0 * (1.0 / library.Media.IF97.Saturation.rho_g(p) - 1.0 / library.Media.IF97.Saturation.rho_f(p)) / library.Media.IF97.Saturation.h_fg(p);
  end if;
end EdwardsTest_IAPWS_CritFlow.pipe.Medium.drho_dh_p;

function(p :: Real * h :: Real) => RealEdwardsTest_IAPWS_CritFlow.pipe.Medium.drho_dp_hfunction EdwardsTest_IAPWS_CritFlow.pipe.Medium.drho_dp_h "∂ρ/∂p|h [kg/(m³·Pa)] from (p, h)"
  input Real p "Pressure [Pa]";
  input Real h "Specific enthalpy [J/kg]";
  output Real val;
  protected Integer reg = EdwardsTest_IAPWS_CritFlow.pipe.Medium.region_ph(p, h);
  protected Real T_val;
algorithm
  if reg == 1 then
    T_val := library.Media.IF97.Region1.T_ph(p, h);
    val := library.Media.IF97.Derivatives.drho_dp_h_R1(p, T_val);
  elseif reg == 2 then
    T_val := library.Media.IF97.Region2.T_ph(p, h);
    val := library.Media.IF97.Derivatives.drho_dp_h_R2(p, T_val);
  else
    val := (library.Media.IF97.Saturation.rho_ph_2phase(p + 500.0, h) - library.Media.IF97.Saturation.rho_ph_2phase(p - 500.0, h)) / 1000.0;
  end if;
end EdwardsTest_IAPWS_CritFlow.pipe.Medium.drho_dp_h;

function(p :: Real * h :: Real) => IntegerEdwardsTest_IAPWS_CritFlow.pipe.Medium.region_phfunction EdwardsTest_IAPWS_CritFlow.pipe.Medium.region_ph "Region flag (1, 2, or 4) from (p, h)"
  input Real p "Pressure [Pa]";
  input Real h "Specific enthalpy [J/kg]";
  output Integer region;
  protected Real hf = library.Media.IF97.Saturation.h_f(p);
  protected Real hg = library.Media.IF97.Saturation.h_g(p);
algorithm
  if h < hf then
    region := 1;
  elseif h > hg then
    region := 2;
  else
    region := 4;
  end if;
end EdwardsTest_IAPWS_CritFlow.pipe.Medium.region_ph;

function(p :: Real * h :: Real) => RealEdwardsTest_IAPWS_CritFlow.pipe.Medium.rho_phfunction EdwardsTest_IAPWS_CritFlow.pipe.Medium.rho_ph "Density [kg/m³] from (p, h)"
  input Real p "Pressure [Pa]";
  input Real h "Specific enthalpy [J/kg]";
  output Real rho_val;
  protected Integer reg = EdwardsTest_IAPWS_CritFlow.pipe.Medium.region_ph(p, h);
  protected Real T_val;
algorithm
  if reg == 1 then
    T_val := library.Media.IF97.Region1.T_ph(p, h);
    rho_val := library.Media.IF97.Region1.rho_pT(p, T_val);
  elseif reg == 2 then
    T_val := library.Media.IF97.Region2.T_ph(p, h);
    rho_val := library.Media.IF97.Region2.rho_pT(p, T_val);
  else
    rho_val := library.Media.IF97.Saturation.rho_ph_2phase(p, h);
  end if;
end EdwardsTest_IAPWS_CritFlow.pipe.Medium.rho_ph;

function(p :: Real * T :: Real) => Reallibrary.Media.IF97.Derivatives.drho_dh_p_R1function library.Media.IF97.Derivatives.drho_dh_p_R1 "∂ρ/∂h|p for Region 1 (compressed liquid) [kg·s²/m⁵  =  kg/(m³·J/kg)]"
  input Real p "Pressure [Pa]";
  input Real T "Temperature [K]  (from Region1.T_ph)";
  output Real val;
  protected Real pi_v = library.Media.IF97.Region1.pi_R1(p);
  protected Real tau_v = library.Media.IF97.Region1.tau_R1(T);
  protected Real gpi = library.Media.IF97.Region1.g_pi(pi_v, tau_v);
  protected Real gpitau = library.Media.IF97.Region1.g_pitau(pi_v, tau_v);
  protected Real gtautau = library.Media.IF97.Region1.g_tautau(pi_v, tau_v);
  protected Real v_val = 461.526 * T / p * pi_v * gpi;
  protected Real dv_dT = 461.526 * pi_v / p * (gpi - tau_v * gpitau);
  protected Real cp_val = -461.526 * tau_v ^ 2.0 * gtautau;
  protected Real rho_val = 1.0 / v_val;
  protected Real drho_dT_p = -rho_val ^ 2.0 * dv_dT;
algorithm
  val := drho_dT_p / cp_val;
end library.Media.IF97.Derivatives.drho_dh_p_R1;

function(p :: Real * T :: Real) => Reallibrary.Media.IF97.Derivatives.drho_dh_p_R2function library.Media.IF97.Derivatives.drho_dh_p_R2 "∂ρ/∂h|p for Region 2 (superheated steam) [kg/(m³·J/kg)]"
  input Real p "Pressure [Pa]";
  input Real T "Temperature [K]  (from Region2.T_ph)";
  output Real val;
  protected Real pi_v = library.Media.IF97.Region2.pi_R2(p);
  protected Real tau_v = library.Media.IF97.Region2.tau_R2(T);
  protected Real gpi = library.Media.IF97.Region2.g_pi_tot(pi_v, tau_v);
  protected Real gpitau = library.Media.IF97.Region2.g_pitau_tot(pi_v, tau_v);
  protected Real gtautau = library.Media.IF97.Region2.g_tautau_tot(pi_v, tau_v);
  protected Real v_val = 461.526 * T / p * pi_v * gpi;
  protected Real dv_dT = 461.526 * pi_v / p * (gpi - tau_v * gpitau);
  protected Real cp_val = -461.526 * tau_v ^ 2.0 * gtautau;
  protected Real rho_val = 1.0 / v_val;
  protected Real drho_dT_p = -rho_val ^ 2.0 * dv_dT;
algorithm
  val := drho_dT_p / cp_val;
end library.Media.IF97.Derivatives.drho_dh_p_R2;

function(p :: Real * T :: Real) => Reallibrary.Media.IF97.Derivatives.drho_dp_h_R1function library.Media.IF97.Derivatives.drho_dp_h_R1 "∂ρ/∂p|h for Region 1 (compressed liquid) [kg/(m³·Pa)]"
  input Real p "Pressure [Pa]";
  input Real T "Temperature [K]  (from Region1.T_ph)";
  output Real val;
  protected Real pi_v = library.Media.IF97.Region1.pi_R1(p);
  protected Real tau_v = library.Media.IF97.Region1.tau_R1(T);
  protected Real gpi = library.Media.IF97.Region1.g_pi(pi_v, tau_v);
  protected Real gpipi = library.Media.IF97.Region1.g_pipi(pi_v, tau_v);
  protected Real gpitau = library.Media.IF97.Region1.g_pitau(pi_v, tau_v);
  protected Real gtautau = library.Media.IF97.Region1.g_tautau(pi_v, tau_v);
  protected Real v_val = 461.526 * T / p * pi_v * gpi;
  protected Real dv_dp = 461.526 * T / (p * p) * pi_v ^ 2.0 * gpipi;
  protected Real dv_dT = 461.526 * pi_v / p * (gpi - tau_v * gpitau);
  protected Real h_p_val = 461.526 * T * pi_v / p * tau_v * gpitau;
  protected Real cp_val = -461.526 * tau_v ^ 2.0 * gtautau;
  protected Real rho_val = 1.0 / v_val;
  protected Real drho_dT_p = -rho_val ^ 2.0 * dv_dT;
  protected Real drho_dp_T = -rho_val ^ 2.0 * dv_dp;
algorithm
  val := drho_dp_T - drho_dT_p * h_p_val / cp_val;
end library.Media.IF97.Derivatives.drho_dp_h_R1;

function(p :: Real * T :: Real) => Reallibrary.Media.IF97.Derivatives.drho_dp_h_R2function library.Media.IF97.Derivatives.drho_dp_h_R2 "∂ρ/∂p|h for Region 2 (superheated steam) [kg/(m³·Pa)]"
  input Real p "Pressure [Pa]";
  input Real T "Temperature [K]  (from Region2.T_ph)";
  output Real val;
  protected Real pi_v = library.Media.IF97.Region2.pi_R2(p);
  protected Real tau_v = library.Media.IF97.Region2.tau_R2(T);
  protected Real gpi = library.Media.IF97.Region2.g_pi_tot(pi_v, tau_v);
  protected Real gpipi = library.Media.IF97.Region2.g_pipi_tot(pi_v, tau_v);
  protected Real gpitau = library.Media.IF97.Region2.g_pitau_tot(pi_v, tau_v);
  protected Real gtautau = library.Media.IF97.Region2.g_tautau_tot(pi_v, tau_v);
  protected Real v_val = 461.526 * T / p * pi_v * gpi;
  protected Real dv_dp = 461.526 * T / (p * p) * pi_v ^ 2.0 * gpipi;
  protected Real dv_dT = 461.526 * pi_v / p * (gpi - tau_v * gpitau);
  protected Real h_p_val = 461.526 * T * pi_v / p * tau_v * gpitau;
  protected Real cp_val = -461.526 * tau_v ^ 2.0 * gtautau;
  protected Real rho_val = 1.0 / v_val;
  protected Real drho_dT_p = -rho_val ^ 2.0 * dv_dT;
  protected Real drho_dp_T = -rho_val ^ 2.0 * dv_dp;
algorithm
  val := drho_dp_T - drho_dT_p * h_p_val / cp_val;
end library.Media.IF97.Derivatives.drho_dp_h_R2;

function(p :: Real * h :: Real) => Reallibrary.Media.IF97.Region1.T_phfunction library.Media.IF97.Region1.T_ph "Temperature from (p, h) in Region 1 [K]"
  input Real p "Pressure [Pa]";
  input Real h "Specific enthalpy [J/kg]";
  output Real T_val;
  protected Real T_iter;
  protected Real f;
  protected Real dT;
algorithm
  T_iter := 400.0;
  for iter in 1:10 loop
    f := library.Media.IF97.Region1.h_pT(p, T_iter) - h;
    dT := -f / library.Media.IF97.Region1.cp_pT(p, T_iter);
    T_iter := T_iter + dT;
  end for;
  T_val := T_iter;
end library.Media.IF97.Region1.T_ph;

function(p :: Real * T :: Real) => Reallibrary.Media.IF97.Region1.cp_pTfunction library.Media.IF97.Region1.cp_pT "Specific heat at constant pressure [J/(kg·K)]"
  input Real p "Pressure [Pa]";
  input Real T "Temperature [K]";
  output Real cp_val;
  protected Real pi_v = library.Media.IF97.Region1.pi_R1(p);
  protected Real tau_v = library.Media.IF97.Region1.tau_R1(T);
algorithm
  cp_val := -461.526 * tau_v ^ 2.0 * library.Media.IF97.Region1.g_tautau(pi_v, tau_v);
end library.Media.IF97.Region1.cp_pT;

function(p :: Real * T :: Real) => Reallibrary.Media.IF97.Region1.h_pTfunction library.Media.IF97.Region1.h_pT "Specific enthalpy [J/kg]"
  input Real p "Pressure [Pa]";
  input Real T "Temperature [K]";
  output Real h_val;
  protected Real pi_v = library.Media.IF97.Region1.pi_R1(p);
  protected Real tau_v = library.Media.IF97.Region1.tau_R1(T);
algorithm
  h_val := 461.526 * T * tau_v * library.Media.IF97.Region1.g_tau(pi_v, tau_v);
end library.Media.IF97.Region1.h_pT;

function(p :: Real) => Reallibrary.Media.IF97.Region1.pi_R1function library.Media.IF97.Region1.pi_R1 "Reduced pressure π = p / p*"
  input Real p "Pressure [Pa]";
  output Real pi;
algorithm
  pi := p / 1.653e7;
end library.Media.IF97.Region1.pi_R1;

function(p :: Real * T :: Real) => Reallibrary.Media.IF97.Region1.rho_pTfunction library.Media.IF97.Region1.rho_pT "Density [kg/m³]"
  input Real p "Pressure [Pa]";
  input Real T "Temperature [K]";
  output Real rho_val;
algorithm
  rho_val := 1.0 / library.Media.IF97.Region1.v_pT(p, T);
end library.Media.IF97.Region1.rho_pT;

function(T :: Real) => Reallibrary.Media.IF97.Region1.tau_R1function library.Media.IF97.Region1.tau_R1 "Reduced temperature τ = T* / T"
  input Real T "Temperature [K]";
  output Real tau;
algorithm
  tau := 1386.0 / T;
end library.Media.IF97.Region1.tau_R1;

function(p :: Real * T :: Real) => Reallibrary.Media.IF97.Region1.v_pTfunction library.Media.IF97.Region1.v_pT "Specific volume [m³/kg]"
  input Real p "Pressure [Pa]";
  input Real T "Temperature [K]";
  output Real v_val;
  protected Real pi_v = library.Media.IF97.Region1.pi_R1(p);
  protected Real tau_v = library.Media.IF97.Region1.tau_R1(T);
algorithm
  v_val := 461.526 * T / p * pi_v * library.Media.IF97.Region1.g_pi(pi_v, tau_v);
end library.Media.IF97.Region1.v_pT;

function(p :: Real * h :: Real) => Reallibrary.Media.IF97.Region2.T_phfunction library.Media.IF97.Region2.T_ph "Temperature from (p, h) in Region 2 [K]"
  input Real p "Pressure [Pa]";
  input Real h "Specific enthalpy [J/kg]";
  output Real T_val;
  protected Real T_iter;
  protected Real f;
  protected Real dT;
algorithm
  T_iter := 600.0;
  for iter in 1:10 loop
    f := library.Media.IF97.Region2.h_pT(p, T_iter) - h;
    dT := -f / library.Media.IF97.Region2.cp_pT(p, T_iter);
    T_iter := T_iter + dT;
  end for;
  T_val := T_iter;
end library.Media.IF97.Region2.T_ph;

function(p :: Real * T :: Real) => Reallibrary.Media.IF97.Region2.cp_pTfunction library.Media.IF97.Region2.cp_pT "Specific heat at constant pressure [J/(kg·K)]"
  input Real p "Pressure [Pa]";
  input Real T "Temperature [K]";
  output Real cp_val;
  protected Real pi_v = library.Media.IF97.Region2.pi_R2(p);
  protected Real tau_v = library.Media.IF97.Region2.tau_R2(T);
algorithm
  cp_val := -461.526 * tau_v ^ 2.0 * library.Media.IF97.Region2.g_tautau_tot(pi_v, tau_v);
end library.Media.IF97.Region2.cp_pT;

function(pi :: Real * tau :: Real) => Reallibrary.Media.IF97.Region2.g0_pifunction library.Media.IF97.Region2.g0_pi "∂g°/∂π = 1/π"
  input Real pi;
  input Real tau;
  output Real v;
algorithm
  v := 1.0 / pi;
end library.Media.IF97.Region2.g0_pi;

function(pi :: Real * tau :: Real) => Reallibrary.Media.IF97.Region2.g0_pipifunction library.Media.IF97.Region2.g0_pipi "∂²g°/∂π² = −1/π²"
  input Real pi;
  input Real tau;
  output Real v;
algorithm
  v := -1.0 / pi ^ 2.0;
end library.Media.IF97.Region2.g0_pipi;

function(pi :: Real * tau :: Real) => Reallibrary.Media.IF97.Region2.g0_taufunction library.Media.IF97.Region2.g0_tau "∂g°/∂τ"
  input Real pi;
  input Real tau;
  output Real v;
algorithm
  v := 10.086655968018 + 0.02804395564151 * tau ^ (-6.0) + (-0.28581095232582) * tau ^ (-5.0) + 1.22131494671784 * tau ^ (-4.0) + (-2.8481638342888) * tau ^ (-3.0) + 4.383951131945 * tau ^ (-2.0) + (-0.56817264921544) * tau + 0.063805391259921 * tau ^ 2.0;
end library.Media.IF97.Region2.g0_tau;

function(pi :: Real * tau :: Real) => Reallibrary.Media.IF97.Region2.g0_tautaufunction library.Media.IF97.Region2.g0_tautau "∂²g°/∂τ²"
  input Real pi;
  input Real tau;
  output Real v;
algorithm
  v := (-0.16826373384906002) * tau ^ (-7.0) + 1.4290547616291 * tau ^ (-6.0) + (-4.88525978687136) * tau ^ (-5.0) + 8.5444915028664 * tau ^ (-4.0) + (-8.76790226389) * tau ^ (-3.0) - 0.56817264921544 + 0.127610782519842 * tau;
end library.Media.IF97.Region2.g0_tautau;

function(pi :: Real * tau :: Real) => Reallibrary.Media.IF97.Region2.g_pi_totfunction library.Media.IF97.Region2.g_pi_tot "∂(g°+g^r)/∂π"
  input Real pi;
  input Real tau;
  output Real v;
algorithm
  v := library.Media.IF97.Region2.g0_pi(pi, tau) + library.Media.IF97.Region2.gr_pi(pi, tau);
end library.Media.IF97.Region2.g_pi_tot;

function(pi :: Real * tau :: Real) => Reallibrary.Media.IF97.Region2.g_pipi_totfunction library.Media.IF97.Region2.g_pipi_tot "∂²(g°+g^r)/∂π²"
  input Real pi;
  input Real tau;
  output Real v;
algorithm
  v := library.Media.IF97.Region2.g0_pipi(pi, tau) + library.Media.IF97.Region2.gr_pipi(pi, tau);
end library.Media.IF97.Region2.g_pipi_tot;

function(pi :: Real * tau :: Real) => Reallibrary.Media.IF97.Region2.g_pitau_totfunction library.Media.IF97.Region2.g_pitau_tot "∂²(g°+g^r)/∂π∂τ"
  input Real pi;
  input Real tau;
  output Real v;
algorithm
  v := library.Media.IF97.Region2.gr_pitau(pi, tau);
end library.Media.IF97.Region2.g_pitau_tot;

function(pi :: Real * tau :: Real) => Reallibrary.Media.IF97.Region2.g_tau_totfunction library.Media.IF97.Region2.g_tau_tot "∂(g°+g^r)/∂τ"
  input Real pi;
  input Real tau;
  output Real v;
algorithm
  v := library.Media.IF97.Region2.g0_tau(pi, tau) + library.Media.IF97.Region2.gr_tau(pi, tau);
end library.Media.IF97.Region2.g_tau_tot;

function(pi :: Real * tau :: Real) => Reallibrary.Media.IF97.Region2.g_tautau_totfunction library.Media.IF97.Region2.g_tautau_tot "∂²(g°+g^r)/∂τ²"
  input Real pi;
  input Real tau;
  output Real v;
algorithm
  v := library.Media.IF97.Region2.g0_tautau(pi, tau) + library.Media.IF97.Region2.gr_tautau(pi, tau);
end library.Media.IF97.Region2.g_tautau_tot;

function(p :: Real * T :: Real) => Reallibrary.Media.IF97.Region2.h_pTfunction library.Media.IF97.Region2.h_pT "Specific enthalpy [J/kg]"
  input Real p "Pressure [Pa]";
  input Real T "Temperature [K]";
  output Real h_val;
  protected Real pi_v = library.Media.IF97.Region2.pi_R2(p);
  protected Real tau_v = library.Media.IF97.Region2.tau_R2(T);
algorithm
  h_val := 461.526 * T * tau_v * library.Media.IF97.Region2.g_tau_tot(pi_v, tau_v);
end library.Media.IF97.Region2.h_pT;

function(p :: Real) => Reallibrary.Media.IF97.Region2.pi_R2function library.Media.IF97.Region2.pi_R2 "Reduced pressure π = p / p*"
  input Real p "Pressure [Pa]";
  output Real pi;
algorithm
  pi := p / 1e6;
end library.Media.IF97.Region2.pi_R2;

function(p :: Real * T :: Real) => Reallibrary.Media.IF97.Region2.rho_pTfunction library.Media.IF97.Region2.rho_pT "Density [kg/m³]"
  input Real p "Pressure [Pa]";
