function(T :: Real) => Reallibrary.Media.IF97.Region2.tau_R2function library.Media.IF97.Region2.tau_R2 "Reduced temperature τ = T* / T"
  input Real T "Temperature [K]";
  output Real tau;
algorithm
  tau := 540.0 / T;
end library.Media.IF97.Region2.tau_R2;

function(p :: Real * T :: Real) => Reallibrary.Media.IF97.Region2.v_pTfunction library.Media.IF97.Region2.v_pT "Specific volume [m³/kg]"
  input Real p "Pressure [Pa]";
  input Real T "Temperature [K]";
  output Real v_val;
  protected Real pi_v = library.Media.IF97.Region2.pi_R2(p);
  protected Real tau_v = library.Media.IF97.Region2.tau_R2(T);
algorithm
  v_val := 461.526 * T / p * pi_v * library.Media.IF97.Region2.g_pi_tot(pi_v, tau_v);
end library.Media.IF97.Region2.v_pT;

function(p :: Real) => Reallibrary.Media.IF97.Saturation.T_satfunction library.Media.IF97.Saturation.T_sat "Saturation temperature [K]  (Newton on p_sat)"
  input Real p "Pressure [Pa]";
  output Real T_val;
  protected Real beta = (p / 1e6) ^ 0.25;
  protected Real T_iter;
  protected Real f;
  protected Real dfdT;
  protected Real theta;
  protected Real A;
  protected Real B;
  protected Real C;
  protected Real dA;
  protected Real dB;
  protected Real dC;
  protected Real dtheta;
  protected Real dp_dT;
  protected Integer iter;
  protected Real E = beta ^ 2.0 + (-17.073846940092) * beta + 14.91510861353;
  protected Real F = 1167.0521452767 * beta ^ 2.0 + 12020.82470247 * beta - 4823.2657361591;
  protected Real G = (-724213.16703206) * beta ^ 2.0 + (-3.2325550322333e6) * beta + 405113.40542057;
  protected Real D = 2.0 * G / (-(F + sqrt(F ^ 2.0 - 4.0 * E * G)));
  protected Real T_guess = (650.17534844798 + D - sqrt((650.17534844798 + D) ^ 2.0 - 4.0 * (650.17534844798 * D - 0.23855557567849))) / 2.0;
algorithm
  T_iter := T_guess;
  for iter in 1:10 loop
    f := library.Media.IF97.Saturation.p_sat(T_iter) - p;
    dp_dT := (library.Media.IF97.Saturation.p_sat(T_iter + 0.005) - library.Media.IF97.Saturation.p_sat(T_iter - 0.005)) / 0.01;
    T_iter := T_iter - f / dp_dT;
  end for;
  T_val := T_iter;
end library.Media.IF97.Saturation.T_sat;

function(p :: Real) => Reallibrary.Media.IF97.Saturation.h_ffunction library.Media.IF97.Saturation.h_f "Saturated liquid enthalpy [J/kg]"
  input Real p "Pressure [Pa]";
  output Real h_val;
  protected Real T_s = library.Media.IF97.Saturation.T_sat(p);
algorithm
  h_val := library.Media.IF97.Region1.h_pT(p, T_s);
end library.Media.IF97.Saturation.h_f;

function(p :: Real) => Reallibrary.Media.IF97.Saturation.h_fgfunction library.Media.IF97.Saturation.h_fg "Latent heat of vaporisation [J/kg]"
  input Real p "Pressure [Pa]";
  output Real h_val;
algorithm
  h_val := library.Media.IF97.Saturation.h_g(p) - library.Media.IF97.Saturation.h_f(p);
end library.Media.IF97.Saturation.h_fg;

function(p :: Real) => Reallibrary.Media.IF97.Saturation.h_gfunction library.Media.IF97.Saturation.h_g "Saturated vapour enthalpy [J/kg]"
  input Real p "Pressure [Pa]";
  output Real h_val;
  protected Real T_s = library.Media.IF97.Saturation.T_sat(p);
algorithm
  h_val := library.Media.IF97.Region2.h_pT(p, T_s);
end library.Media.IF97.Saturation.h_g;

function(T :: Real) => Reallibrary.Media.IF97.Saturation.p_satfunction library.Media.IF97.Saturation.p_sat "Saturation pressure [Pa]  (IAPWS-IF97 Eq. 30)"
  input Real T "Temperature [K]";
  output Real p_val;
  protected Real theta = T + 0.23855557567849 / (-(T - 650.17534844798));
  protected Real A = theta ^ 2.0 + 1167.0521452767 * theta - 724213.16703206;
  protected Real B = (-17.073846940092) * theta ^ 2.0 + 12020.82470247 * theta - 3.2325550322333e6;
  protected Real C = 14.91510861353 * theta ^ 2.0 + (-4823.2657361591) * theta + 405113.40542057;
algorithm
  p_val := 1e6 * (2.0 * C / (sqrt(B ^ 2.0 - 4.0 * A * C) - B)) ^ 4.0;
end library.Media.IF97.Saturation.p_sat;

function(p :: Real * h :: Real) => Reallibrary.Media.IF97.Saturation.quality_phfunction library.Media.IF97.Saturation.quality_ph "Steam quality x ∈ [0,1] from (p,h) in two-phase region"
  input Real p "Pressure [Pa]";
  input Real h "Specific enthalpy [J/kg]";
  output Real x_val;
algorithm
  x_val := (h - library.Media.IF97.Saturation.h_f(p)) / library.Media.IF97.Saturation.h_fg(p);
end library.Media.IF97.Saturation.quality_ph;

function(p :: Real) => Reallibrary.Media.IF97.Saturation.rho_ffunction library.Media.IF97.Saturation.rho_f "Saturated liquid density [kg/m³]"
  input Real p "Pressure [Pa]";
  output Real rho_val;
  protected Real T_s = library.Media.IF97.Saturation.T_sat(p);
algorithm
  rho_val := library.Media.IF97.Region1.rho_pT(p, T_s);
end library.Media.IF97.Saturation.rho_f;

function(p :: Real) => Reallibrary.Media.IF97.Saturation.rho_gfunction library.Media.IF97.Saturation.rho_g "Saturated vapour density [kg/m³]"
  input Real p "Pressure [Pa]";
  output Real rho_val;
  protected Real T_s = library.Media.IF97.Saturation.T_sat(p);
algorithm
  rho_val := library.Media.IF97.Region2.rho_pT(p, T_s);
end library.Media.IF97.Saturation.rho_g;

function(p :: Real * h :: Real) => Reallibrary.Media.IF97.Saturation.rho_ph_2phasefunction library.Media.IF97.Saturation.rho_ph_2phase "Two-phase mixture density [kg/m³]"
  input Real p "Pressure [Pa]";
  input Real h "Specific enthalpy [J/kg]";
  output Real rho_val;
  protected Real x = library.Media.IF97.Saturation.quality_ph(p, h);
  protected Real rf = library.Media.IF97.Saturation.rho_f(p);
  protected Real rg = library.Media.IF97.Saturation.rho_g(p);
algorithm
  rho_val := 1.0 / (x / rg + (1.0 - x) / rf);
end library.Media.IF97.Saturation.rho_ph_2phase;

function(p_cell :: Real * h_mix :: Real * rho :: Real * drho_dp_h :: Real * h_f :: Real * h_g :: Real * rho_f :: Real * p_back :: Real * A_flow :: Real * C_d :: Real * x_trans :: Real * c_floor :: Real) => Reallibrary.Numerics.CriticalFlow.ransom_trappfunction library.Numerics.CriticalFlow.ransom_trapp "Ransom-Trapp critical mass flux [kg/s] at a break face"
  input Real p_cell "Cell pressure adjacent to break [Pa]";
  input Real h_mix "Mixture enthalpy at break cell [J/kg]";
  input Real rho "Mixture density at break cell [kg/m^3]";
  input Real drho_dp_h "drho/dp at constant h [kg/(m^3*Pa)]";
  input Real h_f "Saturated liquid enthalpy [J/kg]";
  input Real h_g "Saturated vapour enthalpy [J/kg]";
  input Real rho_f "Saturated liquid density [kg/m^3]";
  input Real p_back "Back-pressure [Pa]";
  input Real A_flow "Flow area [m^2]";
  input Real C_d "Discharge coefficient [-]";
  input Real x_trans "Quality transition for blend [-] (default 0.10)";
  input Real c_floor "Minimum sound speed [m/s] (default 1200)";
  output Real mdot_crit "Critical mass flow rate [kg/s]";
  protected Real h_fg = max(h_g - h_f, 1000.0);
  protected Real x_local;
  protected Real dp_sub;
  protected Real G_sub;
  protected Real c_hem;
  protected Real G_hem;
  protected Real G_crit;
  protected Real blend;
algorithm
  if h_mix <= h_f then
    x_local := 0.0;
  elseif h_mix >= h_g then
    x_local := 1.0;
  else
    x_local := (h_mix - h_f) / h_fg;
  end if;
  dp_sub := max(p_cell - p_back, 0.0);
  G_sub := sqrt(2.0 * rho_f * dp_sub);
  if drho_dp_h > 0.0 then
    c_hem := max(sqrt(1.0 / (rho * drho_dp_h)), c_floor);
  else
    c_hem := c_floor;
  end if;
  G_hem := rho * c_hem;
  if x_local < x_trans then
    blend := x_local / x_trans;
    G_crit := G_sub * (1.0 - blend) + G_hem * blend;
  else
    G_crit := G_hem;
  end if;
  G_crit := max(G_crit, G_hem);
  mdot_crit := C_d * A_flow * G_crit;
end library.Numerics.CriticalFlow.ransom_trapp;
